import data from "./midi-kits.json";

/**
 * Every MIDI drum kit in the bundle, split into parts (kicks, hi-hats, …).
 *
 * Generated by scripts/render-previews.py. Patterns are played in the browser
 * with the bundle's own one-shots: /public/previews/midi-notes.json holds the
 * scheduled hits per pattern and /public/previews/samples the one-shots.
 */
export type MidiPattern = {
  /** "<kit>/<part>-<n>", the key into midi-notes.json. */
  id: string;
  /** The same file in the credit library (lib/library.json): downloads go through /api/library/<libraryId>. */
  libraryId: string;
  name: string;
  bpm: number;
  /** Seconds, including the ring-out tail. */
  duration: number;
  /** Normalized 0–1 waveform buckets. */
  peaks: number[];
};

export type MidiPart = {
  id: string;
  label: string;
  patterns: MidiPattern[];
};

export type MidiKit = {
  id: string;
  name: string;
  parts: MidiPart[];
};

/** [start seconds, semitones from original pitch, gain, cut seconds (808s)] */
export type MidiHit = [number, number, number, number?];

export type MidiNotes = Record<string, { sample: string; hits: MidiHit[] }>;

export const MIDI_KITS: MidiKit[] = data.kits;
export const MIDI_PATTERN_COUNT = MIDI_KITS.reduce(
  (n, kit) => n + kit.parts.reduce((m, part) => m + part.patterns.length, 0),
  0,
);

export type PartPattern = MidiPattern & { kitId: string; kitName: string };

export type PartGroup = {
  id: string;
  label: string;
  patterns: PartPattern[];
};

/** The same patterns grouped by part across every kit: all kicks, all snares, … */
export const MIDI_PARTS: PartGroup[] = MIDI_KITS.reduce<PartGroup[]>(
  (groups, kit) => {
    for (const part of kit.parts) {
      let group = groups.find((g) => g.id === part.id);
      if (!group) {
        group = { id: part.id, label: part.label, patterns: [] };
        groups.push(group);
      }
      group.patterns.push(
        ...part.patterns.map((p) => ({ ...p, kitId: kit.id, kitName: kit.name })),
      );
    }
    return groups;
  },
  [],
);

/** Seconds of ring-out faded at the end of each pattern. */
export const MIDI_TAIL = 0.4;

export const MIDI_NOTES_SRC = "/previews/midi-notes.json";
export const midiSampleSrc = (sample: string) =>
  `/previews/samples/${sample}.mp3`;
